!function(){"use strict";document.addEventListener("DOMContentLoaded",()=>{!function(){const e=document.getElementById("gh-section-nav"),t=document.querySelectorAll(".gh-nav-link");if(!e)return;const r=Array.from(t).map(e=>({link:e,section:document.getElementById(e.getAttribute("href").replace("#",""))})).filter(e=>e.section),o=e=>{t.forEach(e=>e.classList.remove("active")),e.classList.add("active")};t.forEach(e=>e.addEventListener("click",()=>o(e)));const n=new IntersectionObserver(t=>{t.forEach(t=>{if(t.isIntersecting){const r=e.querySelector(`[href="#${t.target.id}"]`);r&&o(r)}})},{rootMargin:"-40% 0px -50% 0px"});r.forEach(e=>n.observe(e.section))}(),function(){const e=document.querySelectorAll(".reveal");if(!("IntersectionObserver"in window))return void e.forEach(e=>e.classList.add("visible"));const t=new IntersectionObserver(e=>{e.forEach(e=>{e.isIntersecting&&(e.target.classList.add("visible"),t.unobserve(e.target))})},{threshold:.08,rootMargin:"0px 0px -40px 0px"});e.forEach(e=>t.observe(e))}(),window.Journey&&window.Journey.registerSearchItems("frontend/ghogha-port-explorer/index.html",[{id:"ghogha-main",title:"Ghogha Ancient Port Explorer",description:"Explore Ghogha, one of Gujarat's oldest ports with 4,000 years of Arabian Sea trade history from Harappan to colonial periods, on the Gulf of Khambhat.",link:"frontend/ghogha-port-explorer/index.html"},{id:"ghogha-trade",title:"Ghogha Maritime Trade",description:"Trade commodities including salt, cotton textiles, Arabian horses, gems, and ivory. Maritime routes connecting to Arabian Gulf, Persia, and East Africa.",link:"frontend/ghogha-port-explorer/index.html#trade"},{id:"ghogha-timeline",title:"Ghogha Historical Timeline",description:"4,000-year chronological history from Harappan era (2000 BCE) through Mauryan, Solanki, Mughal, and British colonial periods to present day.",link:"frontend/ghogha-port-explorer/index.html#timeline"}])})}();